#include <iostream>
#include <vector>
#include <queue>
#include <complex>
#include <ctime>
#include <chrono>
#include <iomanip>
#include <cassert>
#include <algorithm>
#include <climits>
#include <cmath>
#include <cstring>

using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef pair<ld,ld> pdd;
typedef complex<ld> pt;
typedef vector<pt> pol;
typedef vector<int> vi;

const char nl = '\n';
const ll INF = 0x3f3f3f3f;
const ll INFLL = 0x3f3f3f3f3f3f3f3f;
const ll MOD = 1000000007LL;
const ld EPS = 1e-10;
mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

const int T = 99;
const int C = 12;

struct FlowEdge {
    int to, rev;
    ll flow, cap, cost;
};

FlowEdge adj[5000][5000];
int deg[5000];
ll minCost;

void init(int n) {
    minCost = 0;
    memset(deg, 0, sizeof(deg));
}

void addEdge(int u, int v, ll cap = 1, ll cost = 0) {
    minCost = max(minCost, cap);
    adj[u][deg[u]++] = {v, deg[v], 0, cap, cost};
    adj[v][deg[v]++] = {u, deg[u]-1, 0, 0, -cost};
}

bool vis[5000];
int par[5000];
ll pot[5000], dist[5000];

void init_pot(int n) {
    fill(pot, pot + n, 0);
    for (int iter = 1; iter < n; ++iter) {
        for (int u = 0; u < n; ++u) {
            for (int i = 0; i < deg[u]; ++i) {
                FlowEdge& e = adj[u][i];
                if (e.cap) {
                    pot[e.to] = min(pot[e.to], pot[u] + e.cost);
                }
            }
        }
    }
}

ll mcf(int s, int t, ll& price, int n, bool sparse) {
    fill(vis, vis + n, false);
    fill(dist, dist + n, INF);
    dist[s] = 0;

    if (sparse) {
        queue<int> q;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (vis[u]) continue;
            vis[u] = true;
            for (int i = 0; i < deg[u]; ++i) {
                FlowEdge& e = adj[u][i];
                if (e.flow < e.cap && dist[e.to] > dist[u] + pot[u] - pot[e.to] + e.cost) {
                    dist[e.to] = dist[u] + pot[u] - pot[e.to] + e.cost;
                    par[e.to] = i;
                    q.push(e.to);
                }
            }
        }
    } else {
        for (int u = s; u != -1; ) {
            vis[u] = true;
            for (int i = 0; i < deg[u]; ++i) {
                FlowEdge& e = adj[u][i];
                if (e.flow < e.cap && dist[e.to] > dist[u] + pot[u] - pot[e.to] + e.cost) {
                    dist[e.to] = dist[u] + pot[u] - pot[e.to] + e.cost;
                    par[e.to] = i;
                }
            }
            u = -1;
            ll best = INF;
            for (int i = 0; i < n; ++i) {
                if (!vis[i] && dist[i] < best) {
                    best = dist[u = i];
                }
            }
        }
    }

    if (dist[t] >= INF) return 0;

    ll df = INF;
    for (int u = t; u != s; ) {
        int idx = par[u];
        FlowEdge& rev = adj[u][idx];
        df = min(df, adj[rev.to][rev.rev].cap - adj[rev.to][rev.rev].flow);
        u = rev.to;
    }

    for (int u = t; u != s; ) {
        int idx = par[u];
        FlowEdge& rev = adj[u][idx];
        FlowEdge& e = adj[rev.to][rev.rev];
        e.flow += df;
        rev.flow -= df;
        price += df * e.cost;
        u = rev.to;
    }

    for (int i = 0; i < n; ++i) {
        pot[i] = min(INF, dist[i] + pot[i]);
    }
    return df;
}

ll min_cost_flow(int s, int t, ll& price, int n, bool sparse = false) {
    init_pot(n);
    ll flow = price = 0;
    while (ll df = mcf(s, t, price, n, sparse)) {
        flow += df;
    }
    return flow;
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    cout << fixed << setprecision(10);

    int n,m,k,c,d;
    cin>>n>>m>>k>>c>>d;

    const int source = 0;
    const int sink = n*T+1;

    init(sink+1);

    for(int i=0;i<k;i++) {
        int a;
        cin>>a;
        addEdge(source, a, 1, 0);
    }
    for(int t=0;t<T;t++) {
        addEdge(1+t*n, sink, INF, 0);
        if(t>0) {
            for(int i=1;i<=n;i++) {
                addEdge(i+(t-1)*n, i+t*n, INF, c);
            }
        }
    }

    for(int i=0;i<m;i++) {
        int a, b;
        cin >> a >> b;
        for(int j=0;j<C;j++) {
            int cost = (j+1)*(j+1) - j*j;
            for(int t=1;t<T;t++) {
                addEdge(a+(t-1)*n, b+t*n, 1, cost*d + c);
                addEdge(b+(t-1)*n, a+t*n, 1, cost*d + c);
            }
        }
    }

    ll price, flow = min_cost_flow(source, sink, price, sink+1, true);
    assert(flow==k);
    cout << price << nl;

    return 0;
}
